/* entcore.h - private helpers shared by enterprise.c, tether.c and licence.c (defined in enterprise.c).
 * Not an API: the public headers are enterprise.h and licence.h. Plain C, no stb-style implementation macro.
 */
#ifndef NETMAN_ENTCORE_H
#define NETMAN_ENTCORE_H

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <sys/types.h>
#include <net/if.h>
#include <linux/netlink.h>
#include <linux/rtnetlink.h>

#define ENT_HDR "# generated by netman - do not edit\n"

int ent_fail(int e, const char *fmt, ...); /* sets the text netman_ent_error() returns, returns -|e| */
void ent_cpy(char *d, size_t n, const char *s);
int ent_safe_name(const char *s, size_t max);
char *ent_trim(char *s);
long ent_ms(void);
int ent_mkdirs(const char *p);
int ent_write_atomic(const char *path, const char *data, size_t len, mode_t mode);
int ent_slurp(const char *path, char *buf, size_t n);
/* fork+exec argv (no shell), optional stdin text, stderr+stdout captured into err; -ENOENT if the binary is missing */
int ent_exec(char *const argv[], const char *input, char *err, size_t errn);

struct ent_out {
	char *p;
	size_t n, cap;
};
void ent_put(struct ent_out *o, const char *fmt, ...);

typedef struct {
	int fam, plen; /* plen -1 = none given */
	unsigned char b[16];
} ent_ip;
int ent_parse_ip(const char *s, ent_ip *o, int need_plen);
int ent_iplen(const ent_ip *i);

typedef struct {
	struct nlmsghdr h;
	union {
		struct ifinfomsg i;
		struct ifaddrmsg a;
		struct rtmsg r;
	} m;
	char buf[1024];
} ent_req;
typedef void (*ent_cb)(const struct nlmsghdr *, void *);
void ent_req_init(ent_req *q, int type, int flags, size_t msglen);
void ent_attr(ent_req *q, int type, const void *d, int len);
int ent_nl(ent_req *q, ent_cb cb, void *u);
int ent_idx(const char *ifn); /* ifindex or -ENODEV */

#endif
